@@ -25,14 +25,16 @@ function parseErrorResponseWorkflowMetadata(response: unknown): ISubWorkflowMeta

 export function accumulateTokenUsage(
 	context: IExecuteFunctions,
-	inputTokens: number,
-	outputTokens: number,
+	inputTokens: number | undefined,
+	outputTokens: number | undefined,
 ): void {
+	// Providers may omit either count; ignore anything that isn't a finite number
+	const safe = (n: number | undefined) => (typeof n === 'number' && Number.isFinite(n) ? n : 0);
 	const prev = context.getExecuteData()?.metadata?.tokenUsage;
 	context.setMetadata({
 		tokenUsage: {
-			inputTokens: (prev?.inputTokens ?? 0) + inputTokens,
-			outputTokens: (prev?.outputTokens ?? 0) + outputTokens,
+			inputTokens: safe(prev?.inputTokens) + safe(inputTokens),
+			outputTokens: safe(prev?.outputTokens) + safe(outputTokens),
 		},
 	});
 }
