-					output += usage.completionTokens;
+					if (Number.isFinite(usage.promptTokens)) input += usage.promptTokens;
+					if (Number.isFinite(usage.completionTokens)) output += usage.completionTokens;
 				}
 			}
 		} else if (task.metadata?.tokenUsage) {
 			// Standalone vendor nodes — token data captured via setMetadata before simplify
